  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 1, $j$1.1 Scarcity, Choice and Incentives$j$, $j${"readings": [{"title": "Genesis 41 (King James Version)", "url": "/portal/bible/Genesis/41"}], "body": "Economics is the study of how people make choices when resources are limited. The basic problem is scarcity: wants are unlimited, but time, money, land, labor and tools are not. Because of scarcity, every person, family, business and nation must choose. Economists group resources into land (natural resources), labor (human work), capital (tools, buildings and machines) and entrepreneurship (the skill of organizing the other three to start a business and take risks).\n\nEvery choice has an opportunity cost, which is the value of the next best alternative you give up. If you spend Saturday working a job instead of resting, the rest is part of the cost. Thinking at the margin means weighing the extra benefit of one more unit against its extra cost. People also respond to incentives, which are rewards or penalties that influence behavior. A discount, a bonus, a tax or a fine can all change what people choose.\n\nScripture shows scarcity and wise planning. In Genesis 41:36 Joseph advised Pharaoh that the food shall be for store to the land against the seven years of famine, which shall be in the land of Egypt; that the land perish not through the famine. Joseph saved in the years of plenty so that the nation could eat in the years of want. Proverbs 21:5 says, The thoughts of the diligent tend only to plenteousness; but of every one that is hasty only to want.\n\nWorked example: you have fifty dollars and can buy a pair of shoes or take a friend to a concert. If you choose the shoes, the opportunity cost is the concert. Common mistake: thinking that cost means only the price. Cost also includes what you give up.\n\nYour task: (1) Define scarcity and opportunity cost. (2) Name the four kinds of resources with an example of each. (3) Describe a recent choice you made and its opportunity cost.\n\nFlorida standards: NLPA Economics with Financial Literacy course outcomes, SS.912.E.1, SS.912.FL.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "NLPA Economics with Financial Literacy course outcomes, SS.912.E.1, SS.912.FL", "script": "Welcome to Economics with Financial Literacy. I am Dr. Alex L. Jenkins Sr., and I am glad you are here. Listen, this course will help you understand how the economy works and how to manage your own money with wisdom.\n\nEconomics is the study of how people make choices when resources are limited. That limit is called scarcity. Our wants are unlimited, but our time, money and resources are not. So everyone must choose. The resources are land, labor, capital and entrepreneurship.\n\nNow watch this. Every choice has an opportunity cost. That is the value of the next best thing you give up. If you spend fifty dollars on shoes, the concert you did not attend is your opportunity cost. Cost is more than the price. People also respond to incentives, which are rewards or penalties that change behavior.\n\nJoseph understood scarcity. In Genesis 41:36 he told Pharaoh that the food shall be for store to the land against the seven years of famine. He saved in plenty so the nation could eat in want. Proverbs 21:5 says, The thoughts of the diligent tend only to plenteousness; but of every one that is hasty only to want.\n\nYour task is to define scarcity and opportunity cost, name the four resources and describe a choice you made. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$1.1 Scarcity, Choice and Incentives$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 2, $j$1.2 Supply, Demand and Prices$j$, $j${"readings": [{"title": "Proverbs 11 (King James Version)", "url": "/portal/bible/Proverbs/11"}], "body": "In a market, buyers and sellers meet to trade. Demand is the amount of a good that buyers are willing and able to buy at different prices. The law of demand says that, other things equal, as the price rises, the quantity demanded falls. Supply is the amount that sellers are willing to offer at different prices. The law of supply says that as the price rises, the quantity supplied rises, because higher prices make selling more profitable.\n\nWhere the supply and demand curves cross is the equilibrium price, the price at which the amount buyers want equals the amount sellers offer. If the price is above equilibrium, a surplus appears and sellers lower prices. If the price is below equilibrium, a shortage appears and prices rise. This is how markets send signals without anyone giving orders.\n\nDemand shifts when something other than price changes, such as income, tastes, the price of related goods, or the number of buyers. Supply shifts when costs, technology, or the number of sellers change. A bad harvest cuts supply and raises the price of food. A popular new phone raises demand.\n\nHonest prices matter to God. Proverbs 11:1 says, A false balance is abomination to the LORD: but a just weight is his delight. Proverbs 11:26 adds, He that withholdeth corn, the people shall curse him: but blessing shall be upon the head of him that selleth it. Price gouging in an emergency and cheating customers are not honest dealing.\n\nWorked example: a hurricane closes roads and bottled water becomes scarce. Supply falls, so the price tends to rise, which can attract more shipments. Common mistake: confusing a change in quantity demanded, caused by price, with a change in demand, caused by something else.\n\nYour task: (1) State the laws of supply and demand. (2) Explain equilibrium, surplus and shortage. (3) Give an example of an event that shifts supply and one that shifts demand.\n\nFlorida standards: NLPA Economics with Financial Literacy course outcomes, SS.912.E.1, SS.912.FL.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "NLPA Economics with Financial Literacy course outcomes, SS.912.E.1, SS.912.FL", "script": "Welcome back. Listen, prices are the language of the market, and today you will learn to read it.\n\nDemand is how much buyers are willing and able to buy at different prices. The law of demand says that as the price goes up, the quantity demanded goes down. Supply is how much sellers offer. The law of supply says that as the price goes up, sellers offer more.\n\nNow watch this. Where supply and demand meet is the equilibrium price. Above it, there is a surplus and sellers lower prices. Below it, there is a shortage and prices rise. No one gives orders, yet the market sends signals.\n\nDemand shifts when income, tastes or the number of buyers changes. Supply shifts when costs, technology or the number of sellers changes. A bad harvest cuts supply and raises food prices.\n\nGod cares about honest dealing. Proverbs 11:1 says, A false balance is abomination to the LORD: but a just weight is his delight. Cheating customers or taking cruel advantage in an emergency is not honest.\n\nYour task is to state the two laws, explain equilibrium, surplus and shortage and give an example of a shift in supply and in demand. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$1.2 Supply, Demand and Prices$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 3, $j$1.3 Economic Systems and Free Enterprise$j$, $j${"readings": [{"title": "Proverbs 14 (King James Version)", "url": "/portal/bible/Proverbs/14"}], "body": "Every society must answer three questions: What to produce? How to produce it? For whom to produce it? An economic system is the way a society answers them. In a traditional economy, custom and family roles decide. In a command economy, the government decides and owns most resources. In a market economy, millions of buyers and sellers decide through prices, and private people own property. Most nations use a mixed economy, in which markets do most of the work and government plays some role.\n\nThe United States is mainly a market economy with a role for government. Free enterprise rests on several ideas: private property rights, economic freedom, voluntary exchange, competition, and the profit motive. Profit is the reward for taking risks and serving customers well. Competition pushes businesses to improve quality and lower prices. Government sets the rules by enforcing contracts, protecting property, providing public goods such as roads and defense, and limiting fraud and unfair practices.\n\nThe Bible values work, ownership and fair dealing. Proverbs 14:23 says, In all labour there is profit: but the talk of the lips tendeth only to penury. Deuteronomy 8:18 says, But thou shalt remember the LORD thy God: for it is he that giveth thee power to get wealth. Christians receive business skill as a gift and use it with honesty and generosity, never through theft or oppression.\n\nNo system is perfect. Markets can fail when pollution, monopolies or false information harm others, and command systems often lack incentives and freedom. Citizens should weigh tradeoffs honestly.\n\nWorked example: a family opens a bakery. They own the shop, set their own prices, and compete with other bakeries. If the bread is poor, customers leave. Common mistake: thinking that profit means cheating. Honest profit rewards service.\n\nYour task: (1) Compare traditional, command, market and mixed economies. (2) List four features of free enterprise. (3) Explain one proper role of government in a market.\n\nFlorida standards: NLPA Economics with Financial Literacy course outcomes, SS.912.E.1, SS.912.FL.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "NLPA Economics with Financial Literacy course outcomes, SS.912.E.1, SS.912.FL", "script": "Welcome back. Listen, every nation has to answer three questions: what to produce, how to produce it and for whom.\n\nA traditional economy follows custom. A command economy lets government decide and own most resources. A market economy lets buyers and sellers decide through prices, with private property. Most nations are mixed economies, with markets doing most of the work and government playing a role.\n\nNow watch this. Free enterprise rests on private property, economic freedom, voluntary exchange, competition and the profit motive. Profit rewards risk and good service. Competition pushes businesses to improve quality and lower prices. Government sets the rules: enforcing contracts, protecting property, providing roads and defense and stopping fraud.\n\nScripture honors work and honest gain. Proverbs 14:23 says, In all labour there is profit: but the talk of the lips tendeth only to penury. Deuteronomy 8:18 says, it is he that giveth thee power to get wealth. We use that power with honesty and generosity.\n\nNo system is perfect. Pollution, monopolies and false information can harm people, and command systems often lack freedom and incentives.\n\nYour task is to compare four systems, list four features of free enterprise and explain one role of government. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$1.3 Economic Systems and Free Enterprise$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 4, $j$1.4 Money, Banking and the Federal Reserve$j$, $j${"readings": [{"title": "Proverbs 22 (King James Version)", "url": "/portal/bible/Proverbs/22"}], "body": "Money is anything widely accepted in exchange for goods and services. It does three jobs: a medium of exchange (you can buy things with it), a store of value (it keeps purchasing power over time), and a unit of account (it lets us compare prices). Before money, people used barter, trading goods directly, which required a double coincidence of wants. Money solves that problem. Good money is durable, portable, divisible, scarce and accepted by others. Today money includes coins, paper currency and bank deposits, and more payments are made by card and phone.\n\nBanks take deposits and lend most of the money to borrowers, earning interest from loans and paying savers a smaller rate. This is how savings become loans for homes, cars and businesses. In the United States the Federal Deposit Insurance Corporation, or FDIC, insures deposits at member banks up to two hundred fifty thousand dollars per depositor, per bank, per ownership category.\n\nThe central bank of the United States is the Federal Reserve, created by Congress in 1913. It has a dual mandate: maximum employment and stable prices. Its main tool is influencing interest rates, especially the federal funds rate, and it also buys and sells government securities. When the Fed raises rates, borrowing costs more and spending tends to slow. When it lowers rates, borrowing is cheaper and spending tends to rise.\n\nScripture warns about honest money. Proverbs 22:1 says, A good name is rather to be chosen than great riches, and loving favour rather than silver and gold. Proverbs 16:11 says, A just weight and balance are the LORD'S: all the weights of the bag are his work. Money should be honest, and so should our dealing with it.\n\nWorked example: you deposit one thousand dollars in a savings account at two percent interest. After one year you earn twenty dollars. Common mistake: keeping all savings in cash at home, where it earns nothing and can be lost.\n\nYour task: (1) List the three functions of money. (2) Explain how banks turn savings into loans. (3) Describe the Federal Reserve's two goals.\n\nFlorida standards: NLPA Economics with Financial Literacy course outcomes, SS.912.E.1, SS.912.FL.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "NLPA Economics with Financial Literacy course outcomes, SS.912.E.1, SS.912.FL", "script": "Welcome back. Listen, money is a tool, and you should understand how it works.\n\nMoney is anything widely accepted in exchange. It does three jobs: a medium of exchange, a store of value and a unit of account. Before money people used barter, which was hard because you needed someone who wanted exactly what you had. Good money is durable, portable, divisible, scarce and accepted.\n\nNow watch this. Banks take deposits and lend most of that money to borrowers. They earn interest on loans and pay savers a smaller rate. That is how savings become homes, cars and businesses. The FDIC insures deposits up to two hundred fifty thousand dollars per depositor, per bank, per ownership category.\n\nThe Federal Reserve is our central bank, created in 1913. Its goals are maximum employment and stable prices. When it raises interest rates, borrowing costs more and spending slows. When it lowers rates, borrowing is cheaper and spending tends to rise.\n\nProverbs 22:1 says, A good name is rather to be chosen than great riches. Proverbs 16:11 says, A just weight and balance are the LORD'S. Be honest with money.\n\nYour task is to list the functions of money, explain how banks make loans and describe the Fed's goals. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$1.4 Money, Banking and the Federal Reserve$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'assessment', 1, $j$Assessment 1: Economic Foundations$j$, $j${"prompt": "Write a report of at least 250 words on the foundations of economics. Use complete sentences and label each part. Proverbs 21:5 says, The thoughts of the diligent tend only to plenteousness; but of every one that is hasty only to want.\n\nPart 1: Define scarcity, opportunity cost and incentives, and give an example of each from your own life.\nPart 2: Explain the laws of supply and demand and describe equilibrium, surplus and shortage.\nPart 3: Compare a market economy with a command economy and list four features of free enterprise.\nPart 4: Explain the three functions of money, how banks make loans and the goals of the Federal Reserve.\nPart 5: Explain how honest dealing, as taught in Proverbs 11:1, strengthens an economy.", "rubric": "100 points. Part 1: 20 points. Part 2: 20 points. Part 3: 20 points. Part 4: 20 points. Part 5: 15 points. Complete sentences and conventions: 5 points. A score of 70 or above is passing."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'assessment' and title = $j$Assessment 1: Economic Foundations$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'discussion', 1, $j$Discussion 1: Wise Choices$j$, $j${"prompt": "Write a post of at least 120 words that (1) describes a choice teens often make with limited money or time, (2) names the opportunity cost, (3) explains how an incentive could change the choice, and (4) connects your answer to Proverbs 21:5 or Genesis 41:36. Then write a respectful reply of at least 40 words to another student's post, or answer this question: Why do honest prices matter to a community?"}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'discussion' and title = $j$Discussion 1: Wise Choices$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 1, $j$Check 1.1: Scarcity, Choice and Incentives$j$, $j${"questions": [{"q": "Scarcity means:", "options": ["There is too much of everything", "Money has no value", "Wants are unlimited but resources are limited", "Prices are low"]}, {"q": "Opportunity cost is:", "options": ["The value of the next best alternative you give up", "A kind of profit", "The price tag only", "A tax"]}, {"q": "An incentive is:", "options": ["A government office", "A kind of loan", "A type of resource", "A reward or penalty that influences behavior"]}, {"q": "Which is a capital resource?", "options": ["An idea only", "A forest", "A worker's time", "A machine in a factory"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 1.1: Scarcity, Choice and Incentives$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{2,0,3,3}'::int[], array[$j$Scarcity is the basic economic problem.$j$,$j$Every choice gives something up.$j$,$j$People respond to incentives.$j$,$j$Capital means tools, buildings and machines.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 1.1: Scarcity, Choice and Incentives$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 2, $j$Check 1.2: Supply, Demand and Prices$j$, $j${"questions": [{"q": "The law of demand says that as price rises:", "options": ["Quantity demanded rises", "Quantity demanded falls", "Income rises", "Supply disappears"]}, {"q": "A surplus happens when the price is:", "options": ["Below equilibrium", "Equal to cost", "Above equilibrium", "Zero"]}, {"q": "A bad harvest most directly causes:", "options": ["A decrease in supply", "A decrease in demand", "A lower price", "A tax cut"]}, {"q": "Proverbs 11:1 calls God's delight:", "options": ["A just weight", "A hidden price", "A large profit", "A false balance"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 1.2: Supply, Demand and Prices$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{1,2,0,0}'::int[], array[$j$Buyers buy less at higher prices.$j$,$j$Sellers have more than buyers want.$j$,$j$Less food is offered, so prices tend to rise.$j$,$j$Honest dealing pleases God.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 1.2: Supply, Demand and Prices$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 3, $j$Check 1.3: Economic Systems and Free Enterprise$j$, $j${"questions": [{"q": "In a market economy, most decisions are made by:", "options": ["A single ruler", "Foreign nations", "Custom only", "Buyers and sellers through prices"]}, {"q": "Most nations today have a:", "options": ["Barter only", "No economy", "Pure command economy", "Mixed economy"]}, {"q": "Profit in free enterprise is the reward for:", "options": ["Cheating", "Government gifts", "Taking risks and serving customers", "Avoiding work"]}, {"q": "Deuteronomy 8:18 says it is the LORD who gives:", "options": ["Prices", "Power to get wealth", "Laws of supply", "Taxes"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 1.3: Economic Systems and Free Enterprise$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{3,3,2,1}'::int[], array[$j$Prices guide choices.$j$,$j$Markets and government work together.$j$,$j$Honest profit rewards service.$j$,$j$Our abilities are gifts from God.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 1.3: Economic Systems and Free Enterprise$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 4, $j$Check 1.4: Money, Banking and the Federal Reserve$j$, $j${"questions": [{"q": "Which is NOT a function of money?", "options": ["Medium of exchange", "Producing goods", "Store of value", "Unit of account"]}, {"q": "The FDIC insures deposits up to:", "options": ["$250,000 per depositor, per bank, per category", "$10 million", "Nothing", "$1,000"]}, {"q": "The Federal Reserve was created in:", "options": ["1913", "1999", "1776", "1865"]}, {"q": "When the Fed raises interest rates, borrowing generally:", "options": ["Is free", "Stops completely", "Becomes cheaper", "Becomes more expensive"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 1.4: Money, Banking and the Federal Reserve$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{1,0,0,3}'::int[], array[$j$Money exchanges, stores and measures value.$j$,$j$Insured deposits are protected if a bank fails.$j$,$j$Congress created it in 1913.$j$,$j$Higher rates raise the cost of loans.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 1.4: Money, Banking and the Federal Reserve$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 5, $j$Unit Quiz 1: Economic Foundations$j$, $j${"questions": [{"q": "Scarcity forces people to:", "options": ["Avoid markets", "Print money", "Make choices", "Stop working"]}, {"q": "Opportunity cost is:", "options": ["A kind of tax", "The sale price", "The next best alternative given up", "Profit"]}, {"q": "Land, labor, capital and entrepreneurship are:", "options": ["Four taxes", "Four banks", "Four prices", "The four kinds of resources"]}, {"q": "If the price is below equilibrium, there is a:", "options": ["Shortage", "Surplus", "Monopoly", "Tax"]}, {"q": "A mixed economy combines:", "options": ["Custom only", "No property", "Barter only", "Markets and some government role"]}, {"q": "Which is a proper role of government in a market?", "options": ["Banning competition", "Owning every business", "Enforcing contracts and stopping fraud", "Setting every price"]}, {"q": "The Federal Reserve's goals are maximum employment and:", "options": ["Higher taxes", "Lower wages", "Stable prices", "Fewer banks"]}, {"q": "Proverbs 11:1 says God delights in:", "options": ["A quick profit", "A just weight", "A false balance", "A hidden fee"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 1: Economic Foundations$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{2,2,3,0,3,2,2,1}'::int[], array[$j$Limited resources require choices.$j$,$j$Every choice has a cost.$j$,$j$These are the factors of production.$j$,$j$Buyers want more than sellers offer.$j$,$j$Most nations are mixed.$j$,$j$Rules protect honest trade.$j$,$j$This is its dual mandate.$j$,$j$Honest dealing pleases God.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 1: Economic Foundations$j$ on conflict (item_id) do nothing;
